INSERT INTO public.neuerungen (titel, text) VALUES
  ('Normalarbeitszeit Freitag: 15 min Pause',
   'Mo-Do 7:00-17:00 (1 Std. Pause), Freitag 7:00-12:00 mit 15 min Pause. Die Pause waehlen die Mitarbeiter weiterhin selbst.'),
  ('Lenkzeitverguetung',
   'Am Projekt (Projektuebersicht -> Bearbeiten) traegst du Fahrzeit je Strecke und Entfernung ein. Ab 25 min erscheint bei der Stundenbuchung ein Kaestchen "Fahrer" bzw. "Beifahrer" - die Fahrzeit wird dann automatisch hin und retour als Lenkzeit gebucht. Unter 25 min bleibt alles normale Arbeitszeit.'),
  ('Lenkzeit-Saetze und Auswertung',
   'Die Saetze fuer Fahrer und Beifahrer stehen unter Stammdaten/Personal je Mitarbeiter. Im Stundenbericht gibt es die neue Karte "Lenkzeitverguetung" - Minuten und Betrag je Mitarbeiter, fertig fuer die Lohnverrechnung.');
